head.script:
scwin.onpageload = function() {
	$p.top().scwin.popupIdx = 0;
};

scwin.btn_openWFramePopup1_onclick = function(e) {
	scwin.openPopup("wframePopup");
};

scwin.openPopup = function(type, cmodal) {
	var modal = true;
	if (sbx_modal.getValue() === "false") {
		modal = false;
	}
	var popupName = (type + "_depth1__" + $p.top().scwin.popupIdx) || ("wframePopup" + $p.top().scwin.popupIdx);
	if (modal === true) {
		popupName += " (modal)";
	} else {
		popupName += " (modaless)";
	}
	if (WebSquare._xv !== "SP5") {
		requires("uiplugin.popup");
	}
	var options = {
		id: "popup" + $p.top().scwin.popupIdx,
		type: type,
		width: "580px",
		height: "250px",
		top: "700px",
		left: "10px",
		popupName: popupName,
		modal: cmodal ? cmodal : modal,
		useModalStack: true,
		useModalDisable: false,
		frameModal: 'frame',
		processMsgFrame: true,
		windowMoveType: "overflow",
		resizable: true,
		useMaximize: false,
		status: true,
		menubar: false,
		scrollbars: false,
		title: false
	};
	$p.openPopup("popup.xml", options);
	$p.top().scwin.popupIdx++;
};
